<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/seo-pages.php';
$pages = mapsProspectorSeoPages();
$seoPageKey = isset($seoPageKey) ? (string) $seoPageKey : '';
$page = $pages[$seoPageKey] ?? null;
if (!$page) { http_response_code(404); exit('Página não encontrada.'); }
$baseUrl = 'https://prospec.atendo.log.br';
$canonical = $baseUrl . '/' . $page['slug'] . '.php';
$e = static fn($v): string => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
$same = array_values(array_filter($pages, static fn($p): bool => $p['groupKey'] === $page['groupKey'] && $p['slug'] !== $page['slug']));
$other = array_values(array_filter($pages, static fn($p): bool => $p['groupKey'] !== $page['groupKey']));
$related = array_slice($same, 0, 2);
if ($other) { $related[] = $other[crc32($page['slug']) % count($other)]; }
$faq = [];
foreach ($page['faq'] as $q => $a) { $faq[] = ['@type'=>'Question','name'=>$q,'acceptedAnswer'=>['@type'=>'Answer','text'=>$a]]; }
$jsonLd = ['@context'=>'https://schema.org','@graph'=>[
    ['@type'=>'WebPage','name'=>$page['title'].' | MapsProspector','description'=>$page['focus'],'url'=>$canonical,'inLanguage'=>'pt-BR','isPartOf'=>['@type'=>'WebSite','name'=>'MapsProspector','url'=>$baseUrl.'/']],
    ['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Início','item'=>$baseUrl.'/'],['@type'=>'ListItem','position'=>2,'name'=>$page['label'],'item'=>$canonical],['@type'=>'ListItem','position'=>3,'name'=>$page['title'],'item'=>$canonical]]],
    ['@type'=>'FAQPage','mainEntity'=>$faq],
]];
?>
